import{_ as n,o as t,c as e,a1 as i}from"./chunks/framework.CblolBb6.js";const r="/Pelatihan-WebGIS-BIG/assets/image1.BiKRKBtl.png",s="/Pelatihan-WebGIS-BIG/assets/image2.Be-g7TrE.png",g="/Pelatihan-WebGIS-BIG/assets/image.B85WhtuJ.png",p="/Pelatihan-WebGIS-BIG/assets/image4.BWkn0ym5.png",l="/Pelatihan-WebGIS-BIG/assets/image%201.BXu7uycu.png",m="/Pelatihan-WebGIS-BIG/assets/image6.CbZ9g649.png",u="/Pelatihan-WebGIS-BIG/assets/image%202.BqQTYg1c.png",o="/Pelatihan-WebGIS-BIG/assets/image8.D4U0Z8UA.png",k="/Pelatihan-WebGIS-BIG/assets/image9.B3gFha4m.png",d="/Pelatihan-WebGIS-BIG/assets/image10.CAn4n1V8.png",b="/Pelatihan-WebGIS-BIG/assets/image11.DtXqk3aq.png",h="/Pelatihan-WebGIS-BIG/assets/image12.jVrqaRIa.png",c="/Pelatihan-WebGIS-BIG/assets/image%203.DQpwSLXe.png",f="/Pelatihan-WebGIS-BIG/assets/image14.C9dNtapf.png",I="/Pelatihan-WebGIS-BIG/assets/image15.CQAQop9I.png",_="/Pelatihan-WebGIS-BIG/assets/image16.DhVyUyvb.png",G="/Pelatihan-WebGIS-BIG/assets/image17.L1Ngc3K4.png",y="/Pelatihan-WebGIS-BIG/assets/image%204.JRUWb7g7.png",S="/Pelatihan-WebGIS-BIG/assets/image19.C1w9djsz.png",P="/Pelatihan-WebGIS-BIG/assets/image20.CReMtmjE.png",T="/Pelatihan-WebGIS-BIG/assets/image21.CRBFyxh-.png",B="/Pelatihan-WebGIS-BIG/assets/image22.DwE_3Dka.png",W="/Pelatihan-WebGIS-BIG/assets/image23.B3enZMKZ.png",j="/Pelatihan-WebGIS-BIG/assets/image24.BTYfTdzr.png",C="/Pelatihan-WebGIS-BIG/assets/image25.CjJXOgiK.png",w="/Pelatihan-WebGIS-BIG/assets/image26.Bhhd4x-U.png",D="/Pelatihan-WebGIS-BIG/assets/image%205.DQ0YI0PX.png",v="/Pelatihan-WebGIS-BIG/assets/image28.BOdwsvRJ.png",x="/Pelatihan-WebGIS-BIG/assets/image29.MpzqCqMm.png",L="/Pelatihan-WebGIS-BIG/assets/image30.D2bT3sb7.png",A="/Pelatihan-WebGIS-BIG/assets/image31.CkSrPGEn.png",q="/Pelatihan-WebGIS-BIG/assets/image%206.C4fEVKR1.png",E="/Pelatihan-WebGIS-BIG/assets/image33.CmvsaCy0.png",K="/Pelatihan-WebGIS-BIG/assets/image34.BQcOTbcK.png",O="/Pelatihan-WebGIS-BIG/assets/image35.DZRjIGyA.png",V="/Pelatihan-WebGIS-BIG/assets/image36.65I4jJ6O.png",F="/Pelatihan-WebGIS-BIG/assets/image37.9L0h35C_.png",M="/Pelatihan-WebGIS-BIG/assets/image38.CFJSgVHc.png",R="/Pelatihan-WebGIS-BIG/assets/image39.Cs4jcWrv.png",J="/Pelatihan-WebGIS-BIG/assets/image40.D5sDluD8.png",Q="/Pelatihan-WebGIS-BIG/assets/image41.C6cpMH8x.png",H="/Pelatihan-WebGIS-BIG/assets/image42.hsRxn9MW.png",X="/Pelatihan-WebGIS-BIG/assets/image43.BJ04ijjh.png",N="/Pelatihan-WebGIS-BIG/assets/image44.Zx76K7J5.png",Z="/Pelatihan-WebGIS-BIG/assets/image45.BOst8551.png",z="/Pelatihan-WebGIS-BIG/assets/image46.BCSdXR9c.png",U="/Pelatihan-WebGIS-BIG/assets/image47.CPFAI1Qc.png",Y="/Pelatihan-WebGIS-BIG/assets/image%207.CeN5F5uy.png",$="/Pelatihan-WebGIS-BIG/assets/image%208.CiXceqRI.png",aa="/Pelatihan-WebGIS-BIG/assets/image50.57jrQ6I9.png",na="/Pelatihan-WebGIS-BIG/assets/image%209.BOIAXPRf.png",ta="/Pelatihan-WebGIS-BIG/assets/image%2010.DYud7c0F.png",ea="/Pelatihan-WebGIS-BIG/assets/image%2011.BP9yaD3x.png",ia="/Pelatihan-WebGIS-BIG/assets/image%2012.DQVaTyyN.png",ka=JSON.parse('{"title":"Terrain dan Citra: Integrasi Data Elevasi serta Drapping Citra Satelit","description":"","frontmatter":{},"headers":[],"relativePath":"Training WebGIS BIG/Modul 3 - Pengembangan Frontend Peta Web 3D/Terrain dan Citra Integrasi Data Elevasi serta Dra.md","filePath":"Training WebGIS BIG/Modul 3 - Pengembangan Frontend Peta Web 3D/Terrain dan Citra Integrasi Data Elevasi serta Dra.md"}'),ra={name:"Training WebGIS BIG/Modul 3 - Pengembangan Frontend Peta Web 3D/Terrain dan Citra Integrasi Data Elevasi serta Dra.md"};function sa(ga,a,pa,la,ma,ua){return t(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="terrain-dan-citra-integrasi-data-elevasi-serta-drapping-citra-satelit" tabindex="-1">Terrain dan Citra: Integrasi Data Elevasi serta Drapping Citra Satelit <a class="header-anchor" href="#terrain-dan-citra-integrasi-data-elevasi-serta-drapping-citra-satelit" aria-label="Permalink to &quot;Terrain dan Citra: Integrasi Data Elevasi serta Drapping Citra Satelit&quot;">​</a></h1><h2 id="pembuatan-fungsi-terrain" tabindex="-1"><strong>Pembuatan Fungsi Terrain</strong> <a class="header-anchor" href="#pembuatan-fungsi-terrain" aria-label="Permalink to &quot;**Pembuatan Fungsi Terrain**&quot;">​</a></h2><ol><li><p>Tahap pertama pada folder <strong>components</strong> buat file baru dengan nama <strong>addTerrain.jsx</strong> kemudian buat fungsi <strong>addTerrain</strong> serta tambahkan parameter <strong>viewer</strong> dan parameter <strong>opsi</strong>.</p><p><img src="'+r+'" alt=""></p></li><li><p>Selanjutnya buat fungsi <strong>const Cesium = window.Cesium;</strong> yang digunakan untuk mengambil library Cesium yang telah dimuat pada browser.</p><p><img src="'+s+'" alt=""></p></li><li><p>Pada tahap ketiga buat fungsi untuk untuk mengambil konfigurasi dari parameter opsi yaitu menentukan apakah terrain aktif saat awal aplikasi dijalankan dengan variabel <strong>aktifTerrainAwal</strong>, selanjutnya fungsi callback <strong>onStatusBerubah</strong> untuk mengetahui perubahan status terrain, serta <strong>onLoadingBerubah</strong> untuk mengetahui proses loading terrain.</p><p><img src="'+g+'" alt="image.png"></p></li><li><p>Pada tahap keempat buat fungsi untuk membuat <strong>permukaanDatar</strong> sebagai pengganti terrain 3D ketika terrain dinonaktifkan, membuat variabel <strong>terrainAktif</strong> untuk menyimpan status apakah terrain sedang aktif atau tidak, serta membuat <strong>daftarListenerStatus</strong> sebagai tempat menyimpan fungsi listener yang akan menerima informasi ketika status terrain berubah.</p><p><img src="'+p+'" alt=""></p></li><li><p>Tahap kelima buat fungsi <strong>beritahuStatus()</strong> sebagai wadah untuk mengelola dan menyampaikan informasi ketika terjadi perubahan status pada terrain, seperti saat terrain diaktifkan atau dinonaktifkan.</p><p><img src="'+l+'" alt="image.png"></p></li><li><p>Tahap keenam didalam function <strong>beritahuStatus</strong>, buat fungsi dengan kondisi <strong>if</strong> untuk memeriksa apakah fungsi <strong>onStatusBerubah</strong> tersedia, kemudian mengirimkan informasi status terrain terbaru melalui fungsi tersebut.</p><p><img src="'+m+'" alt=""></p></li><li><p>Selanjutnya tambahkan fungsi mengirimkan informasi status terrain terbaru kepada semua listener yang telah terdaftar di dalam <strong>daftarListenerStatus</strong>.</p><p><img src="'+u+'" alt="image.png"></p></li><li><p>Tahap ketujuh buat fungsi <strong>daftarkanListenerStatus()</strong> yang digunakan untuk menerima dan mendaftarkan listener agar dapat memperoleh informasi ketika status terrain berubah serta tambahkan parameter <strong>callback</strong> atau <strong>cb.</strong></p><p><img src="'+o+'" alt=""></p></li><li><p>Kemudian didalam fungsi tersebut buat kondisi berupa <strong>if</strong> dahulu memastikan bahwa <strong>cb</strong> atau <strong>callback</strong> merupakan sebuah function, kemudian menyimpannya ke dalam <strong>daftarListenerStatus</strong>, lalu langsung mengirimkan status terrain saat ini kepada callback tersebut.</p><p><img src="'+k+'" alt=""></p></li><li><p>Selanjutnya pada tahap kedelapan, buat fungsi <strong>aktifkanTerrain()</strong> yang bertugas untuk memuat dan mengaktifkan terrain 3D pada Cesium Viewer.</p><p><img src="'+d+'" alt=""></p></li><li><p>Tahap berikutnya didalam fungsi tersebut buat kondisi <strong>if</strong> untuk memeriksa apakah fungsi onLoadingBerubah tersedia, kemudian mengirimkan status <strong>true</strong> untuk menandakan bahwa proses pemuatan terrain sedang dimulai.</p><p><img src="'+b+'" alt=""></p></li><li><p>Selanjutnya buat fungsi <strong>Cesium.createWorldTerrainAsync</strong> melakukan proses pemuatan data World Terrain secara asynchronous agar terrain 3D dapat digunakan pada peta.</p><p><img src="'+h+'" alt=""></p></li><li><p>Kemudian pada fungsi <strong>Cesium.createWorldTerrainAsync</strong> tambahkan fungsi buat fungsi <strong>requestVertexNormals: true,</strong> yang digunakan untuk memuat data World Terrain, serta meminta data tambahan berupa vertex normals agar informasi bentuk permukaan terrain dapat digunakan.</p><p><img src="'+c+'" alt="image.png"></p></li><li><p>Tahap selanjutnya buat fungsi <strong>.then()</strong> untuk menjalankan proses selanjutnya setelah data World Terrain berhasil dimuat, kemudian hasil terrain disimpan dalam variabel worldTerrain.</p><p><img src="'+f+'" alt=""></p></li><li><p>Selanjutnya dalam fungsi tersebut tambahkan data <strong>worldTerrain</strong> kemudian tambahkan pada <strong>viewer</strong> sehingga permukaan peta.</p><p><img src="'+I+'" alt=""></p></li><li><p>Tahap berikutnya tambahkan fungsi <strong>terrainAktif= true</strong> untuk menandakan bahwa terrain telah berhasil diaktifkan serta fungsi beritahuStatus() untuk memberitahu callback dan listener bahwa terrain sekarang dalam kondisi aktif.</p><p><img src="'+_+'" alt=""></p></li><li><p>Tahap berikutnya buat fungsi <strong>.finally()</strong> untuk menjalankan proses akhir setelah proses pemuatan terrain selesai serta tambahkan kondisi <strong>if</strong> untuk memeriksa apakah fungsi <strong>onLoadingBerubah</strong> tersedia, kemudian mengirimkan status false untuk menandakan bahwa proses loading terrain telah selesai.</p><p><img src="'+G+'" alt=""></p></li><li><p>Kemudian pada tahap kesembilan buat <strong>function</strong> <strong>matikanTerrain()</strong> yang digunakan untuk menonaktifkan terrain 3D dan mengembalikan tampilan peta ke permukaan datar.</p><p><img src="'+y+'" alt="image.png"></p></li><li><p>Selanjutnya dalam fungsi tersebut tambahkan v<strong>iewer.terrainProvider = permukaanDatar;</strong> yang digunakan untuk mengganti tampilan dengan terrain menjadi tampilan peta dengan permukaan datar. Kemudian tambahkan status <strong>terrainAktif</strong> <strong>= false</strong> untuk menandakan bahwa terrain telah dinonaktifkan serta tambahkan fungsi <strong>beritahuStatus()</strong> untuk memberitahu callback dan listener bahwa terrain sekarang dalam kondisi tidak aktif.</p><p><img src="'+S+'" alt=""></p></li><li><p>Selanjutnya pada tahap kesepuluh <strong>function toggleTerrain()</strong> untuk mengubah status terrain secara otomatis, yaitu mematikan terrain jika sedang aktif dan mengaktifkannya kembali jika sedang tidak aktif.</p><p><img src="'+P+'" alt=""></p></li><li><p>Pada tahap kesebelas buat <strong>functionaturOpacityCitra()</strong> yang digunakan untuk mengatur tingkat transparansi seluruh layer citra pada Cesium Viewer.</p><p><img src="'+T+'" alt=""></p></li><li><p>Selanjutnya dalam fungsi tersebut buat variabel untuk mengambil jumlah seluruh imagery layer yang terdapat pada Cesium Viewer.</p><p><img src="'+B+'" alt=""></p></li><li><p>Selanjutnya tambahkan fungsi untuk mengakses setiap layer citra dengan melakukan perulangan untuk mengakses setiap layer citra yang terdapat di dalam viewer.imageryLayers.</p><p><img src="'+W+'" alt=""></p></li><li><p>Kemudian pada fungsi perulangan tersebut tambahkan fungsi untuk nilai transparansi (alpha) setiap layer citra diubah sesuai dengan nilai yang diberikan.</p><p><img src="'+j+'" alt=""></p></li><li><p>Selanjutnya pada tahap keduabelas buat fungsi <strong>if aktifTerrainAwal;</strong> dengan kondisi jika bernilai true maka terrain langsung diaktifkan, sedangkan jika bernilai false maka viewer menggunakan permukaan datar sebagai kondisi awal.</p><p><img src="'+C+'" alt=""></p></li><li><p>Pada tahap terakhir buat fungsi <strong>return</strong> yang digunakan untuk mengembalikan fungsi-fungsi yang telah dibuat di dalam <strong>addTerrain()</strong> agar dapat digunakan dari luar fungsi meliputi <strong>aktifkanTerrain,</strong> <strong>toggleTerrain, aturOpacityCitra, daftarkanListenerStatus</strong> serta <strong>cekStatusAktif()</strong> untuk memeriksa dan mengembalikan status terrain saat ini melalui nilai <strong>terrainAktif</strong>, yaitu true jika aktif dan false jika tidak aktif.</p><p><img src="'+w+'" alt=""></p></li><li><p>Script keseluruhan untuk addTerrain.jsx dapat dilihat pada gambar berikut ini.</p><p><img src="'+D+'" alt="image.png"></p></li></ol><h2 id="penambahan-panel-terrain-pada-panel-3d-aset" tabindex="-1"><strong>Penambahan Panel Terrain pada Panel 3D Aset</strong> <a class="header-anchor" href="#penambahan-panel-terrain-pada-panel-3d-aset" aria-label="Permalink to &quot;**Penambahan Panel Terrain pada Panel 3D Aset**&quot;">​</a></h2><ol><li><p>Pada tahap pertama dalam <strong>export default function addPanelLayer3D</strong> tambahkan parameter <strong>kontrolTerrain</strong> yang akan digunakan sebagai parameter untuk menambahkan tampilan pengaturan terrain dalam panel.</p><p><img src="'+v+'" alt=""></p></li><li><p>Kemudian pada tahap kedua, dibawah fungsi <strong>Object.entries(daftarLayer)</strong> buat fungsi <strong>if</strong> untuk memeriksa apakah <strong>kontrolTerrain</strong> tersedia sebelum membuat kontrol Terrain dan Citra pada panel.</p><p><img src="'+x+'" alt=""></p></li><li><p>Pada tahap ketiga didalam buat variabel untuk membuat pemisah bagian panel yang akan digunakan sebagai pembatas antara kontrol sebelumnya dengan bagian Terrain dan Citra.</p><p><img src="'+L+'" alt=""></p></li><li><p>Selanjutnya buat elemen <strong>pemisah.style.cssText</strong> yang digunakan sebagai tampilan pemisah dengan garis horizontal, jarak, dan padding agar bagian Terrain dan Citra.</p><p><img src="'+A+'" alt=""></p></li><li><p>Kemudian tambahkan elemen <strong>pemisah.innerHTML</strong> untuk menambahkan judul Terrain &amp; Citra.</p><p><img src="'+q+'" alt="image.png"></p></li><li><p>Tahap berikutnya tambahkan elmen <strong>panel.appendChild(pemisah);</strong> pemisah yang telah dibuat dimasukkan ke dalam panel.</p><p><img src="'+E+'" alt=""></p></li><li><p>Pada tahap keempat buat variabel <strong>const barisTerrain</strong> yang akan digunakan sebagai wadah untuk checkbox dan teks kontrol terrain.</p><p><img src="'+K+'" alt=""></p></li><li><p>Selanjutnya buat elemen <strong>barisTerrain.style.cssText</strong> agar agar checkbox dan teks terrain tersusun secara horizontal.</p><p><img src="'+O+'" alt=""></p></li><li><p>Tahap selanjutnya buat elemen <strong>barisTerrain.innerHTML</strong> yang digunakan untuk membuat checkbox mengaktifkan atau menonaktifkan Terrain (DEM).</p><p><img src="'+V+'" alt=""></p></li><li><p>Pada tahap kelima buat variabel <strong>const cbTerrain</strong> yang digunakan untuk mengambil element input checkbox dari <strong>barisTerrain</strong> dan menyimpannya ke dalam variabel <strong>cbTerrain</strong>.</p><p><img src="'+F+'" alt=""></p></li><li><p>Tahap keenam buat fungsi berupa <strong>cbTerrain.addEventListener(&#39;change&#39;, (e)</strong> yang digunakan untuk mendeteksi ketika pengguna mengubah kondisi checkbox terrain.</p><p><img src="'+M+'" alt=""></p></li><li><p>Selanjutnya pada fungsi tersebut buat kondisi <strong>if</strong> untuk memeriksa apakah checkbox dalam kondisi tercentang; jika tercentang terrain akan diaktifkan, sedangkan jika tidak tercentang terrain akan dinonaktifkan.</p><p><img src="'+R+'" alt=""></p></li><li><p>Tahap ketujuh buat fungsi dan kondisi <strong>if</strong> untuk memeriksa apakah <strong>kontrolTerrain</strong> memiliki fungsi <strong>daftarkanListenerStatus()</strong> yang dapat digunakan untuk menerima perubahan status terrain.</p><p><img src="'+J+'" alt=""></p></li><li><p>Pada tahap berikutnya dalam fungsi tersebut tambahkan fungsi untuk menerima informasi perubahan status terrain, sehingga ketika status terrain berubah menjadi aktif atau tidak aktif, kondisi checkbox akan otomatis diperbarui sesuai nilai <strong>statusAktif</strong>.</p><p><img src="'+Q+'" alt=""></p></li><li><p>Tahap kedelapan buat elemen <strong>barisTerrain</strong> yang berisi checkbox dan teks kontrol Terrain ditambahkan ke dalam panel agar dapat ditampilkan pada antarmuka pengguna.</p><p><img src="'+H+'" alt=""></p></li><li><p>Tahap kesembilan buat variabel <strong>const wrapOpacity</strong> yang digunakan sebagai wadah untuk menempatkan kontrol transparansi citra.</p><p><img src="'+X+'" alt=""></p></li><li><p>Selanjutnya buat elemen <strong>wrapOpacity.style.cssText</strong> untuk mengatur jarak dan warna teks agar kontrol transparansi terlihat lebih rapi di dalam panel.</p><p><img src="'+N+'" alt=""></p></li><li><p>Tahap berikutnya buat elemen <strong>wrapOpacity.innerHTML</strong> untuk mengatur tingkat transparansi citra.</p><p><img src="'+Z+'" alt=""></p></li><li><p>Selanjutnya buat elemen <strong>wrapOpacity.querySelector</strong> yang akan digunakan mendeteksi perubahan nilai slider, kemudian mengirimkan nilai tersebut ke fungsi aturOpacityCitra() untuk mengubah tingkat transparansi citra.</p><p><img src="'+z+'" alt=""></p></li><li><p>Tahap terakhir buat elemen kontrol transparansi citra yang telah dibuat ditambahkan ke dalam panel agar dapat ditampilkan pada antarmuka pengguna.</p><p><img src="'+U+'" alt=""></p></li></ol><h2 id="integrasi-fungsi-terrain-dengan-cesium-viewer" tabindex="-1"><strong>Integrasi Fungsi Terrain dengan Cesium Viewer</strong> <a class="header-anchor" href="#integrasi-fungsi-terrain-dengan-cesium-viewer" aria-label="Permalink to &quot;**Integrasi Fungsi Terrain dengan Cesium Viewer**&quot;">​</a></h2><ol><li><p>Tahap pertama pada file <strong>CesiumViewer.jsx</strong> dalam fungsi berupa <strong>function addContent3D(viewer)</strong> buat fungsi <strong>addTerrain()</strong> dengan parameter viewer untuk membuat kontrol terrain, kemudian konfigurasi <strong>aktifTerrainAwal: true</strong> digunakan agar terrain langsung diaktifkan serta <strong>variabel kontrolTerrain</strong> untuk digunakan mengatur terrain.</p><p><img src="'+Y+'" alt="image.png"></p></li><li><p>Tahap kedua tambahkan <strong>kontrolTerrain</strong> bagai parameter ketiga ke fungsi <strong>addPanelLayer3D()</strong> agar panel layer dapat menggunakan fungsi-fungsi terrain.</p><p><img src="'+$+'" alt="image.png"></p></li><li><p>Tahap terakhir pastikan addTerrain telah terpanggil dan terintegrasi pada halaman <strong>CesiumViewer.jsx</strong>.</p><p><img src="'+aa+'" alt=""></p></li><li><p>Hasil tampilan peta 3d dengan basemap citra satelit sebelum mengaktifkan tampilan terrain.</p><p><img src="'+na+'" alt="image.png"></p></li><li><p>Hasil tampilan peta 3d dengan mengaktifkan tampilan terrain.</p><p><img src="'+ta+'" alt="image.png"></p><p><img src="'+ea+'" alt="image.png"></p></li><li><p>Hasil tampilan ketika mengatur transparansi citra.</p><p><img src="'+ia+'" alt="image.png"></p></li></ol>',7)])])}const da=n(ra,[["render",sa]]);export{ka as __pageData,da as default};
